PANEL = 160
WIDTH = COLS * CELL + PANEL
HEIGHT = ROWS * CELL
FPS = 60

pygame.init()
pygame.key.set_repeat(250, 70)
screen = pygame.display.set_mode((WIDTH, HEIGHT))
pygame.display.set_caption("Tetris")
clock = pygame.time.Clock()
font = pygame.font.SysFont("consolas", 22)
small = pygame.font.SysFont("consolas", 15)


def draw_cell(x, y, color):
    rect = pygame.Rect(x * CELL, y * CELL, CELL, CELL)
    pygame.draw.rect(screen, color, rect)
    pygame.draw.rect(screen, (35, 35, 45), rect, 1)


def draw(game):
    screen.fill((15, 15, 25))
    for y, row in enumerate(game.board.grid):
        for x, kind in enumerate(row):
            if kind:
                draw_cell(x, y, COLORS[kind])
    if game.piece and not game.over:
        for cx, cy in game.piece.cells():
            if cy >= 0:
                draw_cell(cx, cy, COLORS[game.piece.kind])
    pygame.draw.line(screen, (80, 80, 95), (COLS * CELL, 0),
                     (COLS * CELL, HEIGHT), 2)
    px = COLS * CELL + 12
    screen.blit(font.render(f"Score {game.score}", 1, (255, 255, 255)), (px, 20))
    screen.blit(font.render(f"Level {game.level}", 1, (255, 255, 255)), (px, 50))
    screen.blit(font.render(f"Lines {game.lines}", 1, (255, 255, 255)), (px, 80))
    screen.blit(small.render("Next:", 1, (200, 200, 200)), (px, 118))
    for r, row in enumerate(SHAPES[game.next_kind]):
