    screen.blit(small.render("Arrows: move/rotate", 1, (150, 150, 150)), (px, 190))
    screen.blit(small.render("Down: soft drop", 1, (150, 150, 150)), (px, 210))
    screen.blit(small.render("Space: hard drop", 1, (150, 150, 150)), (px, 230))
    screen.blit(small.render("P: pause  R: restart", 1, (150, 150, 150)), (px, 250))
    if game.paused and not game.over:
        text = font.render("PAUSED", 1, (255, 220, 0))
        screen.blit(text, text.get_rect(center=(WIDTH // 2, HEIGHT // 2)))
    if game.over:
        text = font.render("GAME OVER - R to restart", 1, (255, 80, 80))
        screen.blit(text, text.get_rect(center=(WIDTH // 2, HEIGHT // 2)))
